{"explanation":"Each ball makes five left-or-right choices, so its landing bin is determined by how many times it turns right. The animation follows all 32 possible paths: their bin counts are 1, 5, 10, 10, 5, 1—the coefficients of the binomial expansion. Use the slider to see how changing the probability of a right turn changes the theoretical distribution.","manimCode":"const n = 5;
const bx = -3.5;
const step = 0.45;
const pegGap = 0.55;
const coeff = [1, 5, 10, 10, 5, 1];

const leftTitle = new Text({ text: 'Galton board: 5 choices', color: WHITE, fontSize: 29 });
leftTitle.moveTo([-3.5, 3.25, 0]);
const rightTitle = new Text({ text: 'Binomial probabilities', color: WHITE, fontSize: 29 });
rightTitle.moveTo([3.15, 3.25, 0]);
scene.add(leftTitle, rightTitle);

const formula = new MathTex({ latex: 'P(X=k)=\\binom{5}{k}p^k(1-p)^{5-k}' });
await formula.waitForRender();
formula.scale(0.77);
formula.moveTo([3.15, 2.48, 0]);
scene.add(formula);

const divider = new Line({ start: [-0.35, -3.15, 0], end: [-0.35, 2.85, 0], color: GRAY });
const floor = new Line({ start: [bx - 1.55, -2.78, 0], end: [bx + 1.55, -2.78, 0], color: GRAY });
scene.add(divider, floor);

const pegs = [];
for (let r = 0; r < n; r++) {
  for (let j = 0; j <= r; j++) {
    const x = bx + (2 * j - r) * step;
    const y = 2.25 - r * pegGap;
    pegs.push(new Dot({ point: [x, y, 0], radius: 0.055, color: GOLD }));
  }
}
scene.add(...pegs);

for (let k = 0; k <= n; k++) {
  const x = bx + (2 * k - n) * step;
  const guide = new Line({ start: [x + step, -1.12, 0], end: [x + step, -2.78, 0], color: GRAY });
  if (k < n) scene.add(guide);
  const label = new Text({ text: String(k), color: WHITE, fontSize: 23 });
  label.moveTo([x, -3.15, 0]);
  scene.add(label);
}

const boardCaption = new Text({ text: 'number of right turns', color: GRAY, fontSize: 20 });
boardCaption.moveTo([bx, -3.48, 0]);
scene.add(boardCaption);

const travel = new ValueTracker(0);
const pileCount = [0, 0, 0, 0, 0, 0];
const balls = [];
for (let mask = 0; mask < 32; mask++) {
  const bits = Array.from({ length: n }, (_, r) => (mask >> r) & 1);
  const k = bits.reduce((a, b) => a + b, 0);
  const slot = pileCount[k]++;
  const xFinal = bx + (2 * k - n) * step;
  const route = [[bx, 2.76, 0]];
  let rights = 0;
  for (let r = 0; r < n; r++) {
    rights += bits[r];
    route.push([bx + (2 * rights - r - 1) * step, 1.98 - r * pegGap, 0]);
  }
  route.push([xFinal, -2.68 + slot * 0.135, 0]);
  const ball = new Dot({ point: route[0], radius: 0.067, color: TEAL });
  ball.addUpdater(d => {
    const u = Math.max(0, Math.min(6, travel.getValue()));
    const i = Math.min(5, Math.floor(u));
    const f = u - i;
    const a = route[i];
    const b = route[i + 1];
    d.moveTo([a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, 0]);
  });
  balls.push(ball);
}
scene.add(...balls);

const baseY = -2.55;
const centers = Array.from({ length: 6 }, (_, k) => 0.98 + 0.86 * k);
const chartBase = new Line({ start: [0.55, baseY, 0], end: [5.7, baseY, 0], color: GRAY });
scene.add(chartBase);
for (let k = 0; k <= n; k++) {
  const label = new Text({ text: String(k), color: WHITE, fontSize: 23 });
  label.moveTo([centers[k], -2.94, 0]);
  scene.add(label);
}
const chartCaption = new Text({ text: 'k right turns', color: GRAY, fontSize: 20 });
chartCaption.moveTo([3.15, -3.38, 0]);
scene.add(chartCaption);

let p = 0.5;
const reveal = new ValueTracker(0);
const bars = [];
function probability(k) {
  return coeff[k] * Math.pow(p, k) * Math.pow(1 - p, n - k);
}
function updateBar(bar, k) {
  const maxP = Math.max(...coeff.map((_, j) => probability(j)));
  const height = 2.7 * reveal.getValue() * probability(k) / maxP;
  const x = centers[k];
  const w = 0.59;
  bar.setVertices([[x - w / 2, baseY, 0], [x + w / 2, baseY, 0], [x + w / 2, baseY + height, 0], [x - w / 2, baseY + height, 0]]);
}
for (let k = 0; k <= n; k++) {
  const x = centers[k];
  const bar = new Polygon({ vertices: [[x - 0.295, baseY, 0], [x + 0.295, baseY, 0], [x + 0.295, baseY + 0.001, 0], [x - 0.295, baseY + 0.001, 0]], color: BLUE });
  bar.setFill(BLUE, 0.8);
  bar.addUpdater(() => updateBar(bar, k));
  bars.push(bar);
}
scene.add(...bars);

const controls = new Controls(scene, { position: 'top-right', width: 230 });
controls.addSlider({ label: 'Right-turn chance p', min: 0.1, max: 0.9, value: 0.5, step: 0.05, onChange: v => {
  p = v;
  bars.forEach((bar, k) => updateBar(bar, k));
} });

for (let stage = 1; stage <= 6; stage++) {
  await scene.play(travel.animateTo(stage));
}
await scene.play(reveal.animateTo(1));
await scene.wait(999999);"}

